"const fs = require('fs');
const zstd = require('@bokuweb/zstd-wasm');
const { tableFromIPC } = require('apache-arrow');

async function test() {
    await zstd.init();

    const schemaBytes = fs.readFileSync('D:/exploratory/duckdb-extension/deepgraph-arrowtiles-sandbox/public/gaia.arrowtiles.schema');
    const compressedBytes = fs.readFileSync('D:/exploratory/duckdb-extension/deepgraph-arrowtiles-sandbox/public/tile_0_0_0.arrow');

    // ZSTD decompress
    const decompressed = zstd.decompress(compressedBytes);
    console.log("Decompressed size:", decompressed.byteLength);

    const combined = new Uint8Array(schemaBytes.length + decompressed.length);
    combined.set(schemaBytes, 0);
    combined.set(decompressed, schemaBytes.length);

    console.log('Combined size:', combined.length);
    try {
        const table = tableFromIPC(combined);
        console.log('Table parsed successfully.');
        console.log('Table length:', table.length);
        console.log('Table numRows:', table.numRows);

        const child = table.getChild('x_u16');
        if (child) {
            console.log('x_u16 rows:', child.length);
            const arr = child.toArray();
            console.log('x_u16 toArray() length:', arr.length);
            if (arr.length > 0) {
                console.log('First 5 elements:', arr.slice(0, 5));
            }
        } else {
            console.log('x_u16 not found.');
        }
    } catch (e) {
        console.error('Error parsing table:', e);
    }
}

test().catch(console.error);"

