"import { PMTiles } from './node_modules/pmtiles/dist/esm/index.js';
import { ZstdDec } from './node_modules/zstddec/dist/zstddec.esm.js';
import fs from 'fs';

async function run() {
    const file = fs.readFileSync('public/gaia.arrowtiles');
    const p = new PMTiles({
        getBytes: async (offset, length) => {
            const buf = new Uint8Array(length);
            file.copy(buf, 0, offset, offset + length);
            return { data: buf.buffer };
        },
        getKey: () => 'gaia'
    });

    const tile = await p.getZxy(0, 0, 0);
    if (!tile) {
        console.log("Tile not found");
        return;
    }

    let rawData = new Uint8Array(tile.data);
    if (rawData[0] === 0x28 && rawData[1] === 0xB5 && rawData[2] === 0x2F && rawData[3] === 0xFD) {
        const decoder = new ZstdDec();
        await decoder.init();
        rawData = decoder.decode(rawData);
    }

    console.log('Raw data length:', rawData.length);
    console.log('First 16 bytes:', Buffer.from(rawData.buffer, rawData.byteOffset, 16).toString('hex'));

    const view = new DataView(rawData.buffer, rawData.byteOffset);
    if (view.getUint32(0, true) === 0xFFFFFFFF) {
        console.log('Arrow IPC Continuation found!');
        console.log('Message length:', view.getUint32(4, true));
    } else {
        console.log('NO CONTINUATION. First uint32:', view.getUint32(0, true).toString(16));
    }
}
run().catch(console.error);
"

