    const zstddec = await import('zstddec');
    const zstdDecoder = new zstddec.ZSTDDecoder();
    await zstdDecoder.init();
    const rawData = zstdDecoder.decode(new Uint8Array(compressed));

    let validLength = 0;
    const view = new DataView(rawData.buffer, rawData.byteOffset, rawData.byteLength);

    let pos = 0;
    while (pos < rawData.length - 8) {
        const marker = view.getUint32(pos, true);
        if (marker === 0xFFFFFFFF) {
            const length = view.getUint32(pos + 4, true);
            pos += 8 + length;
        } else if (marker === 0) {
            validLength = pos + 4; // include the zero marker
            break;
        } else {
            // It might be the old format length without FFFFFFFF
            if (marker < 100000000) { // Reasonable max length check
                pos += 4 + marker;
            } else {
                break;
            }
        }
    }

    console.log("Valid length found:", validLength, "vs original", rawData.length);

    const validData = rawData.subarray(0, validLength);

    const combinedBuffer = new Uint8Array(schemaFile.length + validData.length);
    combinedBuffer.set(schemaFile, 0);
    combinedBuffer.set(validData, schemaFile.length);

    console.log("Reading truncated buffer...");
    try {
        const table = tableFromIPC(combinedBuffer);
        console.log("Successfully read table. Rows:", table.numRows);
    } catch (e) {
        console.error("Reader failed:", e.message);
    }
}
run().catch(console.error);"

